var SurroundingAyahsModal = class extends import_obsidian.Modal {
  constructor(app, plugin, centerAyah, allAyahs, query) {
    super(app);
    this.plugin = plugin;
    this.centerAyah = centerAyah;
    this.allAyahs = allAyahs;
    this.centerIndex = allAyahs.findIndex(a => a.surah_id === centerAyah.surah_id && a.ayah_id === centerAyah.ayah_id);
    const start = Math.max(0, this.centerIndex - 10);
    const end = Math.min(allAyahs.length - 1, this.centerIndex + 10);
    this.windowAyahs = allAyahs.slice(start, end + 1);
    this.windowStartIndex = start;
    this.centerPosInWindow = this.centerIndex - start;
    this.anchorPos = this.centerPosInWindow;
    this.activePos = this.centerPosInWindow;
    this.selectionFrom = this.centerPosInWindow;
    this.selectionTo = this.centerPosInWindow;
    this.query = query || "";
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("quran-surrounding-modal");
    const header = contentEl.createDiv({ cls: "quran-surrounding-header" });
    header.setText(`\u0622\u06CC\u0627\u062A \u0627\u0637\u0631\u0627\u0641 ${this.centerAyah.surah_name} ${this.centerAyah.ayah_id} - \u2191\u2193 \u062D\u0631\u06A9\u062A\u060C Shift+\u2191\u2193 \u0627\u0646\u062A\u062E\u0627\u0628 \u0686\u0646\u062F\u062A\u0627\u06CC\u06CC\u060C Enter \u062F\u0631\u062C\u060C Esc \u0628\u0633\u062A\u0646`);
    header.style.marginBottom = "12px";
    header.style.fontSize = "0.9em";
    header.style.opacity = "0.8";
    header.setAttribute("dir", "rtl");
    this.listEl = contentEl.createDiv({ cls: "quran-surrounding-list" });
    this.listEl.style.maxHeight = "420px";
    this.listEl.style.overflowY = "auto";
    this.listEl.style.border = "1px solid var(--background-modifier-border)";
    this.listEl.style.borderRadius = "6px";
    this.renderList();
    // Scroll active to middle after render
    setTimeout(() => {
      this.scrollToActive(true);
    }, 50);
    this.scope.register([], "ArrowDown", (evt) => {
      evt.preventDefault();
      this.moveActive(1, false);
      return false;
    });
    this.scope.register([], "ArrowUp", (evt) => {
      evt.preventDefault();
      this.moveActive(-1, false);
      return false;
    });
    this.scope.register(["Shift"], "ArrowDown", (evt) => {
      evt.preventDefault();
      this.moveActive(1, true);
      return false;
    });
    this.scope.register(["Shift"], "ArrowUp", (evt) => {
      evt.preventDefault();
      this.moveActive(-1, true);
      return false;
    });
    this.scope.register([], "Enter", (evt) => {
      evt.preventDefault();
      this.insertSelection(false);
      this.close();
      return false;
    });
    this.scope.register(["Mod"], "Enter", (evt) => {
      evt.preventDefault();
      this.insertSelection(true);
      this.close();
      return false;
    });
  }
  moveActive(delta, withShift) {
    const newPos = Math.max(0, Math.min(this.windowAyahs.length - 1, this.activePos + delta));
    if (newPos === this.activePos) return;
    this.activePos = newPos;
    if (!withShift) {
      this.anchorPos = newPos;
      this.selectionFrom = newPos;
      this.selectionTo = newPos;
    } else {
      this.selectionFrom = Math.min(this.anchorPos, this.activePos);
      this.selectionTo = Math.max(this.anchorPos, this.activePos);
    }
    this.renderList();
    this.scrollToActive(false);
  }
  renderList() {
    if (!this.listEl) return;
    this.listEl.empty();
    this.windowAyahs.forEach((ayah, idx) => {
      const isActive = idx === this.activePos;
      const isSelected = idx >= this.selectionFrom && idx <= this.selectionTo;
      const itemEl = this.listEl.createDiv({ cls: "quran-surrounding-item" });
      itemEl.style.padding = "8px 10px";
      itemEl.style.cursor = "pointer";
      itemEl.style.borderRadius = "4px";
      itemEl.style.margin = "2px 4px";
      itemEl.style.borderRight = isSelected ? "3px solid var(--interactive-accent)" : "3px solid transparent";
      if (isSelected) {
        itemEl.style.backgroundColor = "var(--background-modifier-hover)";
      }
      if (isActive) {
        itemEl.style.outline = "1px solid var(--interactive-accent)";
        itemEl.style.outlineOffset = "-1px";
      }
      itemEl.setAttribute("dir", "rtl");
      const textSpan = itemEl.createDiv();
      try {
        textSpan.innerHTML = `${highlightMatches(ayah.text, this.query)} \uFD3F${toArabicNumerals(ayah.ayah_id)}\uFD3E`;
      } catch (e) {
        textSpan.setText(`${ayah.text} \uFD3F${toArabicNumerals(ayah.ayah_id)}\uFD3E`);
      }
      textSpan.style.marginBottom = "2px";
      const metaSpan = itemEl.createEl("small", { text: `${ayah.surah_name} ${ayah.ayah_id}${idx === this.centerPosInWindow ? " - \u0622\u06CC\u0647 \u062C\u0633\u062A\u062C\u0648 \u0634\u062F\u0647" : ""}${isSelected ? " \u2713" : ""}` });
      metaSpan.style.opacity = "0.7";
      metaSpan.style.fontSize = "0.8em";
      itemEl.addEventListener("click", (e) => {
        if (e.shiftKey) {
          this.activePos = idx;
          this.selectionFrom = Math.min(this.anchorPos, this.activePos);
          this.selectionTo = Math.max(this.anchorPos, this.activePos);
        } else {
          this.activePos = idx;
          this.anchorPos = idx;
          this.selectionFrom = idx;
          this.selectionTo = idx;
        }
        this.renderList();
      });
      itemEl.addEventListener("dblclick", () => {
        this.activePos = idx;
        this.selectionFrom = idx;
        this.selectionTo = idx;
        this.insertSelection();
        this.close();
      });
    });
  }
  scrollToActive(center = false) {
    const activeEl = this.listEl.children[this.activePos];
    if (activeEl) {
      if (center) {
        activeEl.scrollIntoView({ block: "center" });
      } else {
        activeEl.scrollIntoView({ block: "nearest" });
      }
    }
  }
  insertSelection(inline = false) {
    const from = Math.min(this.selectionFrom, this.selectionTo);
    const to = Math.max(this.selectionFrom, this.selectionTo);
    const selectedAyahs = this.windowAyahs.slice(from, to + 1);
    if (selectedAyahs.length === 0) return;
    const view = this.app.workspace.getActiveViewOfType(import_obsidian.MarkdownView);
    const editor = view == null ? void 0 : view.editor;
    if (!editor) {
      new import_obsidian.Notice("No active editor");
      return;
    }
    const { outputFormat, calloutType } = this.plugin.settings;
    const first = selectedAyahs[0];
    const last = selectedAyahs[selectedAyahs.length - 1];
    const header = first.surah_id === last.surah_id ? `${first.surah_name} ${first.ayah_id}-${last.ayah_id}` : `${first.surah_name} ${first.ayah_id} \u0625\u0644\u0649 ${last.surah_name} ${last.ayah_id}`;
    let content = "";
    const formatted = formatAyahsWithGol(selectedAyahs);
    if (inline) {
      content = formatAyahsInline(selectedAyahs);
    } else if (outputFormat === "blockquote") {
      if (selectedAyahs.length === 1) {
        const ayah = selectedAyahs[0];
        const singleGol = formatSingleAyahWithGol(ayah);
        content = `> ${singleGol}\n> \u2014 ${ayah.surah_name} - ${ayah.ayah_id}\n\n`;
      } else {
        content = `> ## ${header}\n>\n> ${formatted}\n\n\n`;
      }
    } else {
      const type = calloutType || "quran";
      if (selectedAyahs.length === 1) {
        const ayah = selectedAyahs[0];
        const singleGol = formatSingleAyahWithGol(ayah);
        content = `> [!${type}] ${ayah.surah_name} - ${ayah.ayah_id}\n> ${singleGol}\n\n`;
      } else {
        content = `> [!${type}] ${header}\n> ${formatted}\n\n`;
      }
    }
    const cursor = editor.getCursor();
    const lines = content.split("\n");
    const lastLine = lines[lines.length - 1] || "";
    const isSingleLine = lines.length === 1;
    editor.transaction({
      changes: [{ from: cursor, to: cursor, text: content }],
      selection: { from: { line: cursor.line + lines.length - 1, ch: isSingleLine ? cursor.ch + content.length : lastLine.length } }
    });
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};



