var FzfPageAyahModal = class extends import_obsidian3.SuggestModal {
  constructor(app, plugin, entry) {
    super(app);
    this.plugin = plugin;
    this.entry = entry;
    this.allItem = { kind: "all", ayahs: entry.ayahs };
    this.singleItems = entry.ayahs.map((ayah) => ({
      kind: "single",
      ayah
    }));
    this.setPlaceholder(`\u0627\u0644\u0635\u0641\u062D\u0629 ${entry.page} \u2014 \u0627\u0628\u062D\u062B \u0641\u064A \u0627\u0644\u0622\u064A\u0627\u062A \u0623\u0648 \u0627\u062E\u062A\u0631...`);
    this.setInstructions([
      { command: "\u21B5", purpose: "insert" },
      { command: "Mod \u21B5", purpose: "insert inline" }
    ]);
    this.scope.register(["Mod"], "Enter", (evt) => {
      this.selectActiveSuggestion(evt);
      return false;
    });
  }
  getSuggestions(query) {
    if (!query.trim()) {
      return [this.allItem, ...this.singleItems];
    }
    const normalizedQ = normalizeArabic(query.trim());
    const filtered = this.singleItems.filter((item) => {
      const { ayah } = item;
      return ayah.normalized_text.includes(normalizedQ) || ayah.ayah_id.toString().includes(query.trim());
    });
    return [this.allItem, ...filtered];
  }
  renderSuggestion(item, el) {
    if (item.kind === "all") {
      const textEl2 = el.createDiv({
        text: `\u0625\u062F\u0631\u0627\u062C \u0627\u0644\u0635\u0641\u062D\u0629 ${this.entry.page} \u0643\u0627\u0645\u0644\u0629`
      });
      textEl2.setAttribute("dir", "rtl");
      el.createEl("small", { text: `${this.entry.ayahs.length} \u0622\u064A\u0629` });
      return;
    }
    const { ayah } = item;
    const textEl = el.createDiv({ text: ayah.text });
    textEl.setAttribute("dir", "rtl");
    el.createEl("small", {
      text: `${ayah.surah_name} - ${ayah.ayah_id}`
    });
  }
  onChooseSuggestion(item, evt) {
    const inline = isInlineEvent(evt);
    if (item.kind === "all") {
      this.insertAllAyahs(item.ayahs, inline);
    } else {
      this.insertSingleAyah(item.ayah, inline);
    }
  }
  insertSingleAyah(ayah, inline = false) {
    const view = this.app.workspace.getActiveViewOfType(import_obsidian3.MarkdownView);
    const editor = view == null ? void 0 : view.editor;
    if (!editor) {
      new import_obsidian3.Notice("Error: No active editor found. Please open a note first.");
      return;
    }
    const { outputFormat, calloutType } = this.plugin.settings;
    const type = calloutType || "quran";
    const singleGol = formatSingleAyahWithGol(ayah);
    const content = inline ? formatAyahsInline([ayah]) : outputFormat === "blockquote" ? `> ${singleGol}\n> \u2014 ${ayah.surah_name} - ${ayah.ayah_id}\n\n` : `> [!${type}] ${ayah.surah_name} - ${ayah.ayah_id}\n> ${singleGol}\n\n`;
    this.insertContent(editor, content);
  }
  insertAllAyahs(ayahs, inline = false) {
    const view = this.app.workspace.getActiveViewOfType(import_obsidian3.MarkdownView);
    const editor = view == null ? void 0 : view.editor;
    if (!editor) {
      new import_obsidian3.Notice("Error: No active editor found. Please open a note first.");
      return;
    }
        const { outputFormat, calloutType } = this.plugin.settings;
    const first = ayahs.at(0);
    const last = ayahs.at(-1);
    if (!first || !last) return;
    const header = `\u0627\u0644\u0635\u0641\u062D\u0629 ${this.entry.page} \u2014 ${first.surah_name} ${first.ayah_id} \u0625\u0644\u0649 ${last.surah_name} ${last.ayah_id}`;
    let content = "";
    const formatted = formatAyahsWithGol(ayahs);
    if (inline) {
      content = formatAyahsInline(ayahs);
    } else if (outputFormat === "blockquote") {
      content = `> ## ${header}\n>\n`;
      content += `> ${formatted}\n\n`;
    } else {
      const type = calloutType || "quran";
      content = `> [!${type}] ${header}\n`;
      content += `> ${formatted}\n\n`;
    }
    this.insertContent(editor, content);
  }
  insertContent(editor, content) {
    const cursor = editor.getCursor();
    editor.replaceRange(content, cursor);
    const lines = content.split("\n");
    const lastLine = lines[lines.length - 1] || "";
    editor.setCursor({
      line: cursor.line + lines.length - 1,
      ch: lastLine.length
    });
  }
};

// src/FzfPageModal.ts
var FzfPageModal = class extends import_obsidian4.SuggestModal {
  constructor(app, plugin) {
    super(app);
    this.pages = [];
    this.plugin = plugin;
    this.setPlaceholder("\u0627\u0643\u062A\u0628 \u0631\u0642\u0645 \u0627\u0644\u0635\u0641\u062D\u0629 (1\u2013604)...");
  }
  async onOpen() {
    void super.onOpen();
    try {
      const pageMap = await quranDataService.getPageMap();
      this.pages = Array.from(pageMap.entries()).sort((a, b) => a[0] - b[0]).map(([page, ayahs]) => ({ page, ayahs }));
      this.inputEl.dispatchEvent(new Event("input"));
    } catch (error) {
      console.error("Failed to load pages:", error);
    }
  }
  getSuggestions(query) {
    if (!query.trim()) return this.pages;
    return this.pages.filter(
      (entry) => entry.page.toString().includes(query.trim())
    );
  }
  renderSuggestion(entry, el) {
    const first = entry.ayahs.at(0);
    const last = entry.ayahs.at(-1);
    if (!first || !last) return;
    const textEl = el.createDiv({
      text: `\u0627\u0644\u0635\u0641\u062D\u0629 ${entry.page}  \u2014  ${entry.ayahs.length} \u0622\u064A\u0629`
    });
    textEl.setAttribute("dir", "rtl");
    const preview = el.createEl("small", {
      text: `${first.surah_name} ${first.ayah_id} \u2190 ${last.surah_name} ${last.ayah_id}`
    });
    preview.setAttribute("dir", "rtl");
  }
  onChooseSuggestion(entry, _evt) {
    new FzfPageAyahModal(this.app, this.plugin, entry).open();
  }
};

